const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Define Petén, Guatemala geometry
    const peten = ee.Geometry.Rectangle([-92.0, 16.0, -89.0, 18.0]); // Approximate bounds for Petén

    // 2. Use Hansen Global Forest Change dataset
    const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

    // 3. Get forest cover baseline (year 2000) and loss/gain through 2023
    const treecover2000 = hansen.select('treecover2000'); // Tree cover in year 2000
    const loss = hansen.select('loss'); // Forest loss (2000-2023)
    const lossyear = hansen.select('lossyear'); // Year of loss
    const gain = hansen.select('gain'); // Forest gain (2000-2012)

    // 4. Calculate forest cover for 2001 (approximately same as 2000 baseline)
    // Consider pixels with >30% tree cover as forest
    const forest2000 = treecover2000.gte(30);

    // 5. Calculate forest cover for 2023
    // Loss by 2001 (lossyear = 1 means loss in 2001)
    const lossBy2001 = lossyear.lte(1).and(loss.eq(1));
    const forest2001 = forest2000.and(lossBy2001.not());

    // Loss by 2023 (lossyear <= 23)
    const lossBy2023 = lossyear.lte(23).and(loss.eq(1));
    const forest2023 = forest2000.and(lossBy2023.not()).or(gain.eq(1));

    // 6. Calculate areas
    const pixelArea = ee.Image.pixelArea();

    const area2001 = forest2001.multiply(pixelArea).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: peten,
      scale: 3000,
      maxPixels: 1e9
    });

    const area2023 = forest2023.multiply(pixelArea).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: peten,
      scale: 3000,
      maxPixels: 1e9
    });

    // Count valid pixels
    const count2001 = forest2001.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: peten,
      scale: 3000,
      maxPixels: 1e9
    });

    const count2023 = forest2023.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: peten,
      scale: 3000,
      maxPixels: 1e9
    });

    const area2001Val = area2001.get('treecover2000').getInfo();
    const area2023Val = area2023.get('treecover2000').getInfo();
    const pixels2001 = count2001.get('treecover2000').getInfo();
    const pixels2023 = count2023.get('treecover2000').getInfo();

    // 7. Validation
    if (pixels2001 === 0 || pixels2023 === 0) {
      console.log('No valid pixels found');
      console.log('<answer>C2</answer>');
      return;
    }

    if (area2001Val === null || area2023Val === null || 
        isNaN(area2001Val) || isNaN(area2023Val)) {
      console.log('Calculation failed - invalid results');
      console.log('<answer>C3</answer>');
      return;
    }

    // Convert to km²
    const forest2001_km2 = area2001Val / 1e6;
    const forest2023_km2 = area2023Val / 1e6;
    const change = forest2023_km2 - forest2001_km2;
    const changePercent = (change / forest2001_km2) * 100;

    // 8. Print results
    console.log(`Forest 2001: ${forest2001_km2.toFixed(2)} km² (Pixels: ${pixels2001})`);
    console.log(`Forest 2023: ${forest2023_km2.toFixed(2)} km² (Pixels: ${pixels2023})`);
    console.log(`Change: ${change.toFixed(2)} km² (${changePercent.toFixed(2)}%)`);

    // 9. Final answer
    if (forest2023_km2 < forest2001_km2) {
      console.log('<answer>A</answer>');
    } else {
      console.log('<answer>B</answer>');
    }

  } catch (error) {
    console.log('Error:', error.message);
    console.log('<answer>D</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
